  "verdict": "revise",
  "summary": "Radio answer spacing reveals the correct answer without the intended differentiation. The shortcut affects the actual batch and three eligible stored questions. Mathematics, grading, rendering and packaging checks passed; the package remains unchanged.",
  "source_analysis": {
    "skill": "Differentiate square-root and reciprocal-square-root functions using the chain rule, then evaluate at a specified point for tangent slopes.",
    "reasoning_steps": [
      "Identify the inner polynomial and outer power.",
      "Differentiate both functions and multiply.",
      "Substitute and simplify.",
      "Evaluate at the stated point when requested."
    ],
    "invariants": [
      "Preserve the observed function families, response formats and difficulty.",
      "Require positive radicands at evaluation points.",
      "Keep the inner-derivative factor, including legitimate zero slopes."
    ],
    "permitted_variations": [
      "Vary coefficients, signs and valid evaluation points.",
      "Vary positive, negative and zero slopes where supported.",
      "Vary distractors and correct-choice positions without revealing the answer through bank construction."
    ],
    "source_refs": [
      "8fcdb2c8-71ca-5bfa-b7fe-49f8f2c05bbb (e-182)",
      "c8b46779-d19f-5cca-987d-5f500a9de334 (q-107360)",
      "67f07fb8-cc06-5cda-9a1f-cc029f68242d (q-107288)",
      "Tutorial 743ad997-8732-5c0f-9676-ff1d44f3b513: differentiate outer and inner functions, multiply, then substitute."
    ],
    "evidence_paths": [
      "source-analysis.json",
      "source-extract.json"
    ]
  },
  "checks": {
