    },
    "decision_variation": {
      "status": "failed",
      "evidence_paths": [
        "pedagogical-variation.json",
        "shortcut--independent-samples.json",
        "shortcut-delivery-batch-accepted.json",
        "counterfactual-results.json",
        "selection-results.json",
        "inventory-results.json"
      ],
      "details": "The spacing strategy succeeds on all 30 tested simple linear-root radios, including all 10 independently delivered easy examples and the actual batch’s radio. Relevant and irrelevant counterfactual checks passed, but delivery and selection do not remove the shortcut."
    }
  },
  "findings": [
    {
      "kind": "decision_shortcut",
      "description": "The production scale_bank makes answers consecutive multiples of a shared factor. Multiplying the common spacing by the visible linear coefficient yields the correct square-root derivative or slope; negating that multiplier handles reciprocal roots. This bypasses outer differentiation and target evaluation despite shuffled positions.",
      "source_refs": [
        "c8b46779-d19f-5cca-987d-5f500a9de334 (q-107360)",
        "67f07fb8-cc06-5cda-9a1f-cc029f68242d (q-107288)",
        "854ec833-4bc0-54f0-9210-c708a9342fef (q-48730)"
      ],
      "reproduction": "Run /home/jake/Developer/Course_Academy/.venv/bin/python -B shortcut_probe.py batch-records.json; exit 1 demonstrates failure. Minimal current case: seed 3173462203, easy, slope_sqrt_radio, parameters a=7,b=37,t=-4. For y=sqrt(37+7x), sorted choices are 1,7/6,4/3,3/2,5/3. Their spacing is 1/6, so choose 7×1/6=7/6 without evaluating the radicand or target. The same record survives delivery.",
      "requested_change": "Replace the family-wide coefficient-ladder bank construction with source-supported distractors that do not disclose the derivative through spacing. Preserve source families and deterministic replay. Retain the executable regression across applicable templates and delivered candidate batches; the script accepts an explicit candidate-records file. Regenerate the runner batch after package repair."
    },
    {
      "kind": "inventory",
      "description": "Three eligible stored radios reproduce the same shortcut: 90db644a-fd4a-5c58-b43a-e0452a6336d1, ab67789f-4616-5914-aa8d-59736a54c4f6, and f48647ea-8ebd-5583-b713-aef1cac5a291. Their stable IDs and content fingerprints match independent generated reproductions.",
      "source_refs": [
        "Inventory basis 5644",
        "98cde390-f268-5ffd-9f2f-31f016a0c432 (q-107303)",
        "854ec833-4bc0-54f0-9210-c708a9342fef (q-48730)",
        "0ce97e32-c8a9-5155-bb70-6cb7385360f5 (q-107291)"
      ],
      "reproduction": "Run /home/jake/Developer/Course_Academy/.venv/bin/python -B inventory_probe.py. Explicit parameters and matching complete records are retained in inventory-results.json and generated-records.json. affected-inventory.json identifies all three entities. Seed 70001 is an independent replay seed, not an asserted historical seed.",
      "requested_change": "After generator repair, the runner should repair or retire these proven eligible generated records, refresh inventory and request independent review. Preserve original source questions and history; no author database write is required."
    }
  ]
}
